   raw=(ROOT/x['source']).read_bytes(); pinned=subprocess.check_output(['git','show',BASE+':'+x['source']],cwd=ROOT)
   need(raw==pinned and hashlib.sha256(raw).hexdigest()==x['source_sha256'],'delegated contract source differs: '+x['id'])
